export const PostgresDestinationConfig = Schema.Struct({ "database": Schema.String.annotate({ "description": "PostgreSQL database name to connect to." }), "schema": Schema.optionalKey(Schema.String.annotate({ "description": "PostgreSQL schema name containing the destination table.", "default": "public" })), "table_name": Schema.optionalKey(Schema.String.annotate({ "description": "PostgreSQL table name to write exported rows into.", "default": "events" })), "has_self_signed_cert": Schema.optionalKey(Schema.Boolean.annotate({ "description": "Legacy SSL option for direct credential configuration. Ignored when using a PostgreSQL integration.", "default": false })) }).annotate({ "description": "Typed configuration for a PostgreSQL batch-export destination.\n\nConnection credentials may live in a linked Integration (when one is provided) or\ninline in this config (legacy). Mirrors the non-credential fields of\n`PostgresBatchExportInputs` in `products/batch_exports/backend/service.py`." })
export type PostgresDestinationRequestTypeEnum = "Postgres"
export const PostgresDestinationRequestTypeEnum = Schema.Literal("Postgres").annotate({ "description": "* `Postgres` - Postgres" })
export type PrecomputationMode = "precomputed" | "direct"
export const PrecomputationMode = Schema.Literals(["precomputed", "direct"]).annotate({ "title": "PrecomputationMode" })
export type PreprocessingConfig = { readonly "diffs_n"?: number | null, readonly "lags_n"?: number | null, readonly "smooth_n"?: number | null }
export const PreprocessingConfig = Schema.Struct({ "diffs_n": Schema.optionalKey(Schema.Union([Schema.Number.check(Schema.isInt()), Schema.Null]).annotate({ "title": "Diffs N", "description": "Order of differencing. 0 = raw values, 1 = first-order diffs (default: 0)", "default": null })), "lags_n": Schema.optionalKey(Schema.Union([Schema.Number.check(Schema.isInt()), Schema.Null]).annotate({ "title": "Lags N", "description": "Number of lag features. 0 = none, >0 = include n lagged values (default: 0)", "default": null })), "smooth_n": Schema.optionalKey(Schema.Union([Schema.Number.check(Schema.isInt()), Schema.Null]).annotate({ "title": "Smooth N", "description": "Moving average window size. 0 = no smoothing, >1 = smooth over n points (default: 0)", "default": null })) }).annotate({ "title": "PreprocessingConfig" })
export type PreviewInviteRequest = { readonly "interviewee_identifier"?: string }
export const PreviewInviteRequest = Schema.Struct({ "interviewee_identifier": Schema.optionalKey(Schema.String.annotate({ "description": "Which targeted interviewee to render the preview for (an email or PostHog distinct ID already on the topic). Leave blank to preview for the first targeted interviewee." }).check(Schema.isMaxLength(400))) })
export type PreviewInviteResult = { readonly "interviewee_identifier": string, readonly "user_name": string, readonly "email": string, readonly "subject": string, readonly "html": string, readonly "interview_url": string, readonly "emailable": boolean, readonly "is_preview_link": boolean }
export const PreviewInviteResult = Schema.Struct({ "interviewee_identifier": Schema.String.annotate({ "description": "The identifier (email or distinct ID) the preview was rendered for." }), "user_name": Schema.String.annotate({ "description": "The display name used in the email greeting, derived from the identifier." }), "email": Schema.Union([Schema.String.annotate({ "description": "The email address the invite would be sent to. Null for distinct-ID-only interviewees.", "format": "email" })]), "subject": Schema.String.annotate({ "description": "The rendered subject line (saved topic subject, sanitized, or the default)." }), "html": Schema.String.annotate({ "description": "The fully rendered, CSS-inlined HTML body of the invite email. Safe to display in a sandboxed iframe." }), "interview_url": Schema.String.annotate({ "description": "An illustrative placeholder interview link shown in the previewed email body. The preview never exposes a real per-recipient share token — that link is minted only when invites are sent.", "format": "uri" }), "emailable": Schema.Boolean.annotate({ "description": "True if this interviewee has an email address and could actually receive the invite." }), "is_preview_link": Schema.Boolean.annotate({ "description": "Always true — the previewed interview_url is an illustrative placeholder, never a live link." }) })
export type PreviewProxyInvokeRequest = { readonly "message"?: string, readonly "session_id"?: string }
export const PreviewProxyInvokeRequest = Schema.Struct({ "message": Schema.optionalKey(Schema.String.annotate({ "description": "User message to deliver to the agent. Required for `run` (starts the session) and `send` (appends to it); ignored for `cancel` / `listen`." })), "session_id": Schema.optionalKey(Schema.String.annotate({ "description": "Target session id for `send` — the running session to append the message to. Omit for `run` (a fresh session is created)." })) }).annotate({ "description": "Body forwarded verbatim to the agent ingress for a *preview* invoke of a\nnon-live revision. The meaningful shape depends on the `rest` path segment:\n\n- `run` — `{ message }`: the user message that starts a new session.\n- `send` — `{ session_id, message }`: append a message to a running session.\n- `cancel` / `listen` — no body.\n\nDocuments `message` / `session_id` so the generated MCP tool exposes them;\nany extra keys are still forwarded as-is to ingress." })
