export const SignalReportRefundResponse = Schema.Struct({ "id": Schema.String.annotate({ "readOnly": true, "format": "uuid" }), "reason": Schema.Literals(["pr_incorrect", "pr_not_useful", "duplicate", "other"]).annotate({ "description": "* `pr_incorrect` - PR incorrect\n* `pr_not_useful` - PR not useful\n* `duplicate` - Duplicate\n* `other` - Other", "readOnly": true }), "note": Schema.String.annotate({ "description": "Optional free-form note captured with the refund.", "readOnly": true }), "billing_path": Schema.Literals(["excluded", "credited"]).annotate({ "description": "* `excluded` - Excluded\n* `credited` - Credited", "readOnly": true }), "credits": Schema.Number.annotate({ "description": "Signals credits refunded (flat per-PR charge snapshot; 1 credit = $0.01).", "readOnly": true }).check(Schema.isInt()), "pr_url": Schema.String.annotate({ "description": "The refunded implementation PR's GitHub URL, snapshotted at refund time.", "readOnly": true }), "pr_run_created_at": Schema.String.annotate({ "description": "When the first billable PR run was created — the charge this reverses.", "readOnly": true, "format": "date-time" }), "credit_amount_usd": Schema.Union([Schema.String.check(Schema.isPattern(new RegExp("^-?\\d{0,8}(?:\\.\\d{0,2})?$"), { "description": "USD amount the billing service credited (credited path only). Null until the sync completes; '0.00' is a legitimate outcome (e.g. the PR was inside the free tier).", "readOnly": true, "format": "decimal" }))]), "billing_synced": Schema.Boolean.annotate({ "description": "Whether the billing service has acknowledged this refund. Always relevant for the credited path (the Stripe credit is issued asynchronously); excluded-path refunds need no billing sync and report false.", "readOnly": true }), "created_at": Schema.String.annotate({ "description": "When the refund was created.", "readOnly": true, "format": "date-time" }), "already_refunded": Schema.Boolean.annotate({ "description": "True when the report already had a refund and that existing refund is returned unchanged — refunds are one-per-report and repeat calls are idempotent.", "default": false, "readOnly": true }) })
export type SignalReportRefundSummaryResponse = { readonly "credited_refund_count": number, readonly "credited_credits": number, readonly "period_billable_credits": number }
export const SignalReportRefundSummaryResponse = Schema.Struct({ "credited_refund_count": Schema.Number.annotate({ "description": "Number of credited-path refunds across the whole organization whose refunded PR run falls in the current billing period. Excluded-path refunds never reach billing usage, so they are deliberately absent." }).check(Schema.isInt()), "credited_credits": Schema.Number.annotate({ "description": "Total signals credits those refunds returned (1 credit = $0.01). Divide by the flat per-PR charge to get the number of PRs to subtract from billing usage." }).check(Schema.isInt()), "period_billable_credits": Schema.Number.annotate({ "description": "The organization's live billable signals credits for the current billing period, computed by the same rules as the nightly usage report — including PRs created today that billing hasn't recorded yet, and already excluding refund-excluded and billing-exempt reports. Take the max of this and billing's recorded usage for a live PR count that reacts to new PRs and same-day refunds immediately." }).check(Schema.isInt()) })
