export const SignalReportStateRequest = Schema.Struct({ "state": Schema.Literals(["suppressed", "potential", "resolved"]).annotate({ "description": "* `suppressed` - suppressed\n* `potential` - potential\n* `resolved` - resolved" }), "dismissal_reason": Schema.optionalKey(Schema.Literals(["already_fixed", "report_unclear", "analysis_wrong", "wontfix_intentional", "wontfix_irrelevant", "other"]).annotate({ "description": "* `already_fixed` - Already fixed\n* `report_unclear` - Report is unclear to me\n* `analysis_wrong` - Agent's analysis is wrong\n* `wontfix_intentional` - Won't fix - intentional behavior\n* `wontfix_irrelevant` - Won't fix - issue is real but insignificant\n* `other` - Something else…" })), "dismissal_note": Schema.optionalKey(Schema.String.annotate({ "description": "Optional free-form note explaining the dismissal. Capped at 4000 characters." }).check(Schema.isMaxLength(4000))), "snooze_for": Schema.optionalKey(Schema.Number.annotate({ "description": "Optional, only honored when state is 'potential'. Number of additional signals the report must accumulate before it is re-promoted into the pipeline — effectively snoozing it until then. Omit to let the report re-enter the pipeline on the next matching signal." }).check(Schema.isInt()).check(Schema.isGreaterThanOrEqualTo(1)).check(Schema.isLessThanOrEqualTo(100000))) })
