export const SignalScoutManualRun = Schema.Struct({ "skill_name": Schema.String.annotate({ "description": "The `signals-scout-*` skill that was dispatched." }), "workflow_id": Schema.String.annotate({ "description": "Temporal workflow id for the dispatched run. The run executes asynchronously; poll the scout's runs to see the resulting run row, its status, and any emitted findings." }), "started": Schema.Boolean.annotate({ "description": "True when a new run was dispatched. The endpoint returns 409 instead when a run for this scout is already in progress." }) }).annotate({ "description": "Response for an on-demand (`run now`) scout dispatch.\n\nThe run executes asynchronously on the Temporal worker, so there is no `SignalScoutRun`\nrow yet at response time — the bridge row is created once the run's first turn starts.\nPoll the scout's runs (`scout-runs-list`) to see the resulting run and its findings." })
