export const SlackThreadContextRepoResearch = Schema.Struct({ "task_id": Schema.String.annotate({ "description": "UUID of the internal repo-research Task." }), "run_id": Schema.String.annotate({ "description": "UUID of the internal repo-research TaskRun." }), "status": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Research run status, or null if the run row could not be loaded." }), "task_processing_workflow_id": Schema.String.annotate({ "description": "Temporal workflow id for the research sandbox run (`task-processing-<task_id>-<run_id>`, or a caller-prefixed variant)." }), "task_processing_workflow_url": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Full Temporal Web UI URL for the research workflow; null when `TEMPORAL_UI_HOST` is unset." }), "sandbox_url": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Live sandbox tunnel URL for the research run, when one was attached." }), "task_view_url": Schema.String.annotate({ "description": "Absolute URL to the research task detail page (carries `?ph_debug=true`)." }), "log_url": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Presigned S3 URL for the research run's JSONL log transcript (valid ~1 hour)." }) }).annotate({ "description": "The internal sandbox run the discovery agent used to pick this run's repo.\n\nOnly present when the originating mention was ambiguous (multiple candidate\nrepos, no explicit mention) — that's the only path that spins up a research\nsandbox. Null otherwise." })
