export const SlackThreadContextTask = Schema.Struct({ "id": Schema.String.annotate({ "description": "UUID of the Task row." }), "team_id": Schema.Number.annotate({ "description": "Team that owns the task." }).check(Schema.isInt()), "title": Schema.String.annotate({ "description": "Task title (typically the first ~255 chars of the Slack ask)." }), "repository": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Resolved repository in `org/repo` form, or null if the run started without a repo." }), "origin_product": Schema.String.annotate({ "description": "`Task.OriginProduct` (`slack` for slack-originated tasks)." }), "created_at": Schema.String.annotate({ "description": "When the task was created (server-side timestamp).", "format": "date-time" }), "url": Schema.String.annotate({ "description": "Absolute URL to the task detail page in the PostHog app." }) }).annotate({ "description": "The PostHog Task linked to the Slack thread." })
