export const SuggestTagsRequest = Schema.Struct({ "prompt": Schema.String.annotate({ "description": "The classifier's instruction prompt — the single dimension to categorize sessions by." }).check(Schema.isMaxLength(10000)), "tags": Schema.optionalKey(Schema.Array(Schema.String.check(Schema.isMaxLength(200))).annotate({ "description": "The current tag vocabulary, so suggestions never duplicate a tag the user already has." }).check(Schema.isMaxLength(200))), "multi_label": Schema.optionalKey(Schema.Boolean.annotate({ "description": "Whether the classifier assigns multiple tags per session.", "default": true })), "allow_freeform_tags": Schema.optionalKey(Schema.Boolean.annotate({ "description": "Whether the classifier may emit tags outside the fixed vocabulary.", "default": false })), "scanner_id": Schema.optionalKey(Schema.Union([Schema.String.annotate({ "description": "Existing scanner to ground suggestions in its own observations (the tags and reasoning it has already produced on real recordings). Omit for an unsaved scanner.", "format": "uuid" })])) }).annotate({ "description": "Body of POST /vision/scanners/suggest_tags/ — the classifier config currently being edited." })
export type SuggestedReviewer = { readonly "github_login"?: string, readonly "user_uuid"?: string, readonly "reason"?: string }
export const SuggestedReviewer = Schema.Struct({ "github_login": Schema.optionalKey(Schema.String.annotate({ "description": "GitHub login (case-insensitive, stored lowercased) — e.g. `octocat`, no `@`, no display name. Resolve one via `scout-members-list` (each member row carries a resolved `github_login`) or git history when you only have a name." }).check(Schema.isMaxLength(200))), "user_uuid": Schema.optionalKey(Schema.String.annotate({ "description": "PostHog user UUID (e.g. from `scout-members-list`, or an entity's `created_by`). Resolved server-side to the member's linked GitHub login — use this when you know the PostHog user but not their GitHub handle. Must be a concrete UUID; the `@me` alias is not valid here.", "format": "uuid" })), "reason": Schema.optionalKey(Schema.Union([Schema.String.check(Schema.isMaxLength(500, { "description": "One sentence of evidence for WHY this person: what ties them to the affected surface (e.g. 'authored 4 of the last 10 commits touching products/tracing/mcp/', 'human correction routed the prior tracing report to them'). Persisted on the report so the routing is auditable — always set it when you can name the evidence; 'precedent' alone is weak, prefer code-derived ownership." }))])) }).annotate({ "description": "One suggested reviewer — identified by `github_login`, `user_uuid`, or both.\n\nThe server canonicalizes each entry to a lowercased GitHub login: a `user_uuid` is resolved to the\norg member's linked GitHub login (and wins over a supplied `github_login` when both are given). A\n`user_uuid` that isn't an org member of this team with a linked GitHub identity is rejected — so a\nreviewer is never silently dropped." })
