export type TeamCIHealthItem = { readonly "owner_team": string, readonly "flaky_test_count": number, readonly "flaky_test_count_prior": number, readonly "regression_test_count": number, readonly "regression_test_count_prior": number, readonly "failed_run_count": number, readonly "failed_run_count_prior": number, readonly "same_commit_recovery_run_count": number, readonly "same_commit_recovery_run_count_prior": number, readonly "quarantined_failed_run_count": number, readonly "quarantined_failed_run_count_prior": number, readonly "last_seen_at": string }
export const TeamCIHealthItem = Schema.Struct({ "owner_team": Schema.String.annotate({ "description": "Owning team slug (the CODEOWNERS handle minus '@PostHog/', e.g. 'team-replay'), or the literal 'unowned' for tests whose spans carry no ownership stamp." }), "flaky_test_count": Schema.Number.annotate({ "description": "Owned tests one commit was seen both failing and passing in the window: the same proof, and the same word, that flaky_tests calls a confirmed_flake. Compare with flaky_test_count_prior for the delta." }).check(Schema.isInt()), "flaky_test_count_prior": Schema.Number.annotate({ "description": "Same count over the equal-length window immediately before date_from." }).check(Schema.isInt()), "regression_test_count": Schema.Number.annotate({ "description": "Owned tests that failed with no recorded same-commit recovery and still hit the blast-radius bar (a master/main failure, or min_failed_prs distinct PRs). Not flakes: absence of proof, not proof." }).check(Schema.isInt()), "regression_test_count_prior": Schema.Number.annotate({ "description": "Same count over the prior window." }).check(Schema.isInt()), "failed_run_count": Schema.Number.annotate({ "description": "CI runs (not spans) where an owned test's recorded outcome was failed or error. An absolute count, not a rate: fast passing runs are not emitted." }).check(Schema.isInt()), "failed_run_count_prior": Schema.Number.annotate({ "description": "Same count over the prior window." }).check(Schema.isInt()), "same_commit_recovery_run_count": Schema.Number.annotate({ "description": "Runs where one commit both failed and passed an owned test: a re-run attempt went green, or an in-job retry recovered it." }).check(Schema.isInt()), "same_commit_recovery_run_count_prior": Schema.Number.annotate({ "description": "Same count over the prior window." }).check(Schema.isInt()), "quarantined_failed_run_count": Schema.Number.annotate({ "description": "Runs where an owned test failed while quarantined (xfail): masked in CI, still failing." }).check(Schema.isInt()), "quarantined_failed_run_count_prior": Schema.Number.annotate({ "description": "Same count over the prior window." }).check(Schema.isInt()), "last_seen_at": Schema.String.annotate({ "description": "Most recent failure, recovery, or xfail run across the team's owned tests, either window.", "format": "date-time" }) })
