export const Breakdown = Schema.Struct({ "group_type_index": Schema.optionalKey(Schema.Union([Schema.Number.check(Schema.isInt()), Schema.Null]).annotate({ "title": "Group Type Index", "default": null })), "histogram_bin_count": Schema.optionalKey(Schema.Union([Schema.Number.check(Schema.isInt()), Schema.Null]).annotate({ "title": "Histogram Bin Count", "default": null })), "normalize_url": Schema.optionalKey(Schema.Union([Schema.Boolean, Schema.Null]).annotate({ "title": "Normalize Url", "default": null })), "property": Schema.Union([Schema.String, Schema.Number.check(Schema.isInt())]).annotate({ "title": "Property" }), "type": Schema.optionalKey(Schema.Union([MultipleBreakdownType, Schema.Null]).annotate({ "default": null })) }).annotate({ "title": "Breakdown" })
