export const AlertCheck = Schema.Struct({ "id": Schema.String.annotate({ "readOnly": true, "format": "uuid" }), "created_at": Schema.String.annotate({ "readOnly": true, "format": "date-time" }), "calculated_value": Schema.Never, "state": Schema.Literals(["Firing", "Not firing", "Errored", "Snoozed"]).annotate({ "readOnly": true, "description": "* `Firing` - Firing\n* `Not firing` - Not firing\n* `Errored` - Errored\n* `Snoozed` - Snoozed" }), "targets_notified": Schema.Boolean.annotate({ "readOnly": true }), "anomaly_scores": Schema.Json.annotate({ "readOnly": true }), "triggered_points": Schema.Json.annotate({ "readOnly": true }), "triggered_dates": Schema.Json.annotate({ "readOnly": true }), "interval": Schema.Union([Schema.String, Schema.Null]).annotate({ "readOnly": true }), "triggered_metadata": Schema.Json.annotate({ "readOnly": true }), "investigation_status": Schema.Union([InvestigationStatusEnum, NullEnum], { mode: "oneOf" }).annotate({ "readOnly": true }), "investigation_verdict": Schema.Union([InvestigationVerdictEnum, NullEnum], { mode: "oneOf" }).annotate({ "readOnly": true }), "investigation_summary": Schema.Union([Schema.String, Schema.Null]).annotate({ "readOnly": true }), "investigation_notebook_short_id": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Short ID of the Notebook produced by the investigation agent, when the agent ran for this check.", "readOnly": true }), "notification_sent_at": Schema.Union([Schema.String.annotate({ "readOnly": true, "format": "date-time" })]), "notification_suppressed_by_agent": Schema.Boolean.annotate({ "readOnly": true }) })
export type AwsS3DestinationConfig = { readonly "bucket_name": string, readonly "region": string, readonly "prefix": string, readonly "compression"?: CompressionEnum | NullEnum, readonly "file_format"?: "Parquet" | "JSONLines", readonly "max_file_size_mb"?: number | null, readonly "encryption"?: string | null, readonly "kms_key_id"?: string | null }
export const AwsS3DestinationConfig = Schema.Struct({ "bucket_name": Schema.String.annotate({ "description": "Name of the destination bucket." }), "region": Schema.String.annotate({ "description": "Region the bucket is in (e.g. 'us-east-1')." }), "prefix": Schema.String.annotate({ "description": "Object key prefix applied to every exported file." }), "compression": Schema.optionalKey(Schema.Union([CompressionEnum, NullEnum], { mode: "oneOf" }).annotate({ "description": "Optional compression codec applied to exported files. Valid codecs depend on file_format.\n\n* `brotli` - brotli\n* `gzip` - gzip\n* `lz4` - lz4\n* `snappy` - snappy\n* `zstd` - zstd" })), "file_format": Schema.optionalKey(Schema.Literals(["Parquet", "JSONLines"]).annotate({ "description": "* `Parquet` - Parquet\n* `JSONLines` - JSONLines", "default": "JSONLines" })), "max_file_size_mb": Schema.optionalKey(Schema.Union([Schema.Number.check(Schema.isInt()), Schema.Null]).annotate({ "description": "If set, rolls to a new file once the current file exceeds this size in MB." })), "encryption": Schema.optionalKey(Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Optional S3 server-side encryption algorithm (e.g. 'AES256' or 'aws:kms')." })), "kms_key_id": Schema.optionalKey(Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "KMS key ID to use when encryption is 'aws:kms'." })) }).annotate({ "description": "Typed configuration for an AWS S3 batch-export destination.\n\nAWS credentials live in the linked aws-s3 Integration. Mirrors the non-credential fields of\n`AwsS3BatchExportInputs` in `products/batch_exports/backend/service.py`." })
export type AzureBlobDestinationConfig = { readonly "container_name": string, readonly "prefix"?: string, readonly "compression"?: CompressionEnum | NullEnum, readonly "file_format"?: "Parquet" | "JSONLines", readonly "max_file_size_mb"?: number | null }
export const AzureBlobDestinationConfig = Schema.Struct({ "container_name": Schema.String.annotate({ "description": "Azure Blob Storage container name." }), "prefix": Schema.optionalKey(Schema.String.annotate({ "description": "Object key prefix applied to every exported file.", "default": "" })), "compression": Schema.optionalKey(Schema.Union([CompressionEnum, NullEnum], { mode: "oneOf" }).annotate({ "description": "Optional compression codec applied to exported files. Valid codecs depend on file_format.\n\n* `brotli` - brotli\n* `gzip` - gzip\n* `lz4` - lz4\n* `snappy` - snappy\n* `zstd` - zstd" })), "file_format": Schema.optionalKey(Schema.Literals(["Parquet", "JSONLines"]).annotate({ "description": "* `Parquet` - Parquet\n* `JSONLines` - JSONLines", "default": "JSONLines" })), "max_file_size_mb": Schema.optionalKey(Schema.Union([Schema.Number.check(Schema.isInt()), Schema.Null]).annotate({ "description": "If set, rolls to a new file once the current file exceeds this size in MB." })) }).annotate({ "description": "Typed configuration for an Azure Blob Storage batch-export destination.\n\nCredentials live in the linked Integration, not in this config. Mirrors\n`AzureBlobBatchExportInputs` in `products/batch_exports/backend/service.py`." })
export type BlastRadius = { readonly "affected": number, readonly "total": number, readonly "limit": number, readonly "dedupe_key": DedupeKeyEnum | NullEnum, readonly "confirm_token": string }
export const BlastRadius = Schema.Struct({ "affected": Schema.Number.annotate({ "description": "Number of users matching the filters" }).check(Schema.isInt()), "total": Schema.Number.annotate({ "description": "Total number of users" }).check(Schema.isInt()), "limit": Schema.Number.annotate({ "description": "Maximum allowed audience size for batch triggers for this team." }).check(Schema.isInt()), "dedupe_key": Schema.Union([DedupeKeyEnum, NullEnum], { mode: "oneOf" }).annotate({ "description": "The dedupe key that was actually applied to 'affected'. 'email' means it counts unique email addresses; null means it counts persons.\n\n* `email` - email" }), "confirm_token": Schema.String.annotate({ "description": "Proof this audience was previewed: pass it to the batch dispatch (confirm_token) after echoing 'affected' to the user. Signs these exact filters; expires in 15 minutes." }) })
export type BlastRadiusRequest = { readonly "filters": { readonly [x: string]: Schema.Json }, readonly "group_type_index"?: number | null, readonly "dedupe_key"?: DedupeKeyEnum | NullEnum }
export const BlastRadiusRequest = Schema.Struct({ "filters": Schema.Record(Schema.String, Schema.Json).annotate({ "description": "Property filters to apply" }), "group_type_index": Schema.optionalKey(Schema.Union([Schema.Number.check(Schema.isInt()), Schema.Null]).annotate({ "description": "Group type index for group-based targeting" })), "dedupe_key": Schema.optionalKey(Schema.Union([DedupeKeyEnum, NullEnum], { mode: "oneOf" }).annotate({ "description": "When 'email', count unique email addresses instead of persons, matching how batch email sends deduplicate recipients.\n\n* `email` - email" })) })
export type EndExperiment = { readonly "conclusion"?: ConclusionEnum | NullEnum, readonly "conclusion_comment"?: string, readonly "open_cleanup_pr"?: boolean }
export const EndExperiment = Schema.Struct({ "conclusion": Schema.optionalKey(Schema.Union([ConclusionEnum, NullEnum], { mode: "oneOf" }).annotate({ "description": "The conclusion of the experiment.\n\n* `won` - won\n* `lost` - lost\n* `inconclusive` - inconclusive\n* `stopped_early` - stopped_early\n* `invalid` - invalid" })), "conclusion_comment": Schema.optionalKey(Schema.Union([Schema.String.check(Schema.isMaxLength(4000, { "description": "Optional comment about the experiment conclusion." }))])), "open_cleanup_pr": Schema.optionalKey(Schema.Boolean.annotate({ "description": "When true, open a draft pull request that removes the experiment's feature-flag code from the linked repository. Requires the requesting user to have access to PostHog Desktop (403 otherwise). Only acts for allowlisted teams; ignored otherwise.", "default": false })) })
