export const ProjectProfile = Schema.Struct({ "profile_id": Schema.String.annotate({ "description": "UUID of the `SignalProjectProfile` row." }), "computed_at": Schema.String.annotate({ "description": "ISO-8601 timestamp the profile was built." }), "expires_at": Schema.String.annotate({ "description": "ISO-8601 timestamp after which the profile is considered stale." }), "source_version": Schema.String.annotate({ "description": "Schema version of the inventory builder. Bumps invalidate older cached rows." }), "payload": Schema.Struct({ "inventory": Schema.Struct({ "project_context": Schema.Struct({ "product_description": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Human-set product description on the project (max 1000 chars). When present, the most direct \"what does this team's product do\" answer. `null` when unset." }), "app_urls": Schema.Array(Schema.String).annotate({ "description": "Registered app URLs for this team (toolbar / replay). The team's actual product surface; complements `$pageview.$host` discovery via `read-data-schema`." }) }).annotate({ "description": "`inventory.project_context` — free-form orientation about the project's product." }), "products_in_use": Schema.Array(Schema.String).annotate({ "description": "Product keys this team has completed onboarding for, sorted alphabetically." }), "product_intents": Schema.Array(ProductIntentEntry).annotate({ "description": "Products the team signaled intent to use; useful for spotting stuck onboardings." }), "integrations": Schema.Array(IntegrationEntry).annotate({ "description": "Connected integrations (kind + connection time only — config never surfaced)." }), "external_data_sources": Schema.Array(ExternalDataSourceEntry).annotate({ "description": "Connected warehouse sources (excludes soft-deleted)." }), "signal_source_configs": Schema.Struct({ "enabled": Schema.Array(SignalSourceConfigEntry).annotate({ "description": "Source configs the team has explicitly enabled." }), "disabled": Schema.Array(SignalSourceConfigEntry).annotate({ "description": "Source configs the team has explicitly disabled (different from never wired up)." }) }).annotate({ "description": "`inventory.signal_source_configs` split into enabled and disabled buckets." }), "emit_eligibility": Schema.Struct({ "ai_processing_approved": Schema.Boolean.annotate({ "description": "Whether the organization has approved AI data processing (an org-level gate on all scout emits)." }), "source_enabled": Schema.Boolean.annotate({ "description": "Whether the `signals_scout` signal source is enabled for this team." }), "can_emit": Schema.Boolean.annotate({ "description": "True only when both team/org-level gates pass, so scout findings (signal and report channels alike) actually reach the inbox. When False, every emit is silently dropped — quick-close instead of doing throwaway investigation. Does not account for a scout's own dry-run `emit` toggle, which is per-config, not team-wide." }), "remediation": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "One-line next step to unblock emits when `can_emit` is False; null when emits can flow." }) }).annotate({ "description": "`inventory.emit_eligibility` — whether scout findings can reach the inbox for this team." }), "existing_inbox_reports": Schema.Struct({ "total": Schema.Number.annotate({ "description": "Total non-deleted, non-suppressed reports for this team." }).check(Schema.isInt()), "by_status": Schema.Array(InboxReportStatusBucket).annotate({ "description": "Per-status breakdown of inbox reports." }) }).annotate({ "description": "`inventory.existing_inbox_reports` — what's already been surfaced to the inbox." }), "recent_activity": Schema.Struct({ "window_days": Schema.Number.annotate({ "description": "Lookback window in days the per-scope counts cover." }).check(Schema.isInt()), "by_scope": Schema.Array(ScopeActivityEntry).annotate({ "description": "Per-scope activity rows, busiest scope first. Triage which entity type the team has worked in lately." }) }).annotate({ "description": "`inventory.recent_activity` — per-scope counts off the activity log." }), "recent_reviewer_corrections": Schema.Struct({ "window_days": Schema.Number.annotate({ "description": "Lookback window in days the corrections cover." }).check(Schema.isInt()), "corrections": Schema.Array(ReviewerCorrectionEntry).annotate({ "description": "Human reviewer edits, newest first. A human swapping a report's suggested reviewers is authoritative ownership precedent — route to who they chose." }) }).annotate({ "description": "`inventory.recent_reviewer_corrections` — human edits to report reviewer lists." }), "recent_dashboards": Schema.Array(RecentDashboardEntry).annotate({ "description": "Up to 20 dashboards on this team sorted by `last_accessed_at` desc — what the team is currently looking at, not necessarily the most-trafficked. We don't have per-dashboard view counts in Postgres, only the timestamp of the most recent access." }), "recent_surveys": Schema.Struct({ "total_count": Schema.Number.annotate({ "description": "Total surveys on the team." }).check(Schema.isInt()), "active_count": Schema.Number.annotate({ "description": "Surveys that are live (not archived, started, and not yet ended)." }).check(Schema.isInt()), "recent": Schema.Array(RecentSurveyEntry).annotate({ "description": "The 5 most recently updated surveys." }) }).annotate({ "description": "`inventory.recent_surveys` — total + active count, plus the 5 most recently modified." }), "recent_feature_flags": Schema.Struct({ "total_count": Schema.Number.annotate({ "description": "Total non-deleted feature flags on the team." }).check(Schema.isInt()), "active_count": Schema.Number.annotate({ "description": "Flags currently evaluating (`active=true`)." }).check(Schema.isInt()), "recent": Schema.Array(RecentFeatureFlagEntry).annotate({ "description": "The 5 most recently updated non-deleted flags." }) }).annotate({ "description": "`inventory.recent_feature_flags` — total + active count, plus the 5 most recently modified." }), "recent_experiments": Schema.Struct({ "total_count": Schema.Number.annotate({ "description": "Total experiments on the team." }).check(Schema.isInt()), "running_count": Schema.Number.annotate({ "description": "Experiments currently running (started, not ended, not archived)." }).check(Schema.isInt()), "recent": Schema.Array(RecentExperimentEntry).annotate({ "description": "The 5 most recently updated experiments." }) }).annotate({ "description": "`inventory.recent_experiments` — total + currently-running count, plus the 5 most recently modified." }), "recent_alerts": Schema.Struct({ "total_count": Schema.Number.annotate({ "description": "Total insight alerts on the team." }).check(Schema.isInt()), "enabled_count": Schema.Number.annotate({ "description": "Alerts currently armed (`enabled=true`)." }).check(Schema.isInt()), "recent": Schema.Array(RecentAlertEntry).annotate({ "description": "The 5 most recently created alerts." }) }).annotate({ "description": "`inventory.recent_alerts` — total + currently-enabled count, plus the 5 most recently created." }), "recent_hog_functions": Schema.Struct({ "total_count": Schema.Number.annotate({ "description": "Total non-deleted hog functions on the team." }).check(Schema.isInt()), "enabled_count": Schema.Number.annotate({ "description": "Hog functions currently enabled (`enabled=true`)." }).check(Schema.isInt()), "recent": Schema.Array(RecentHogFunctionEntry).annotate({ "description": "The 5 most recently updated hog functions." }) }).annotate({ "description": "`inventory.recent_hog_functions` — total + enabled count, plus the 5 most recently modified." }), "recent_hog_flows": Schema.Struct({ "total_count": Schema.Number.annotate({ "description": "Total hog flows on the team." }).check(Schema.isInt()), "active_count": Schema.Number.annotate({ "description": "Hog flows that are not archived." }).check(Schema.isInt()), "recent": Schema.Array(RecentHogFlowEntry).annotate({ "description": "The 5 most recently updated hog flows." }) }).annotate({ "description": "`inventory.recent_hog_flows` — total + non-archived count, plus the 5 most recently modified." }), "recent_notebooks": Schema.Struct({ "total_count": Schema.Number.annotate({ "description": "Total non-deleted notebooks on the team." }).check(Schema.isInt()), "recent": Schema.Array(RecentNotebookEntry).annotate({ "description": "The 5 most recently modified notebooks." }) }).annotate({ "description": "`inventory.recent_notebooks` — total + the 5 most recently modified." }), "recent_cohorts": Schema.Struct({ "total_count": Schema.Number.annotate({ "description": "Total non-deleted cohorts on the team." }).check(Schema.isInt()), "recent": Schema.Array(RecentCohortEntry).annotate({ "description": "The 5 most recently created cohorts." }) }).annotate({ "description": "`inventory.recent_cohorts` — total + the 5 most recently created." }), "recent_actions": Schema.Struct({ "total_count": Schema.Number.annotate({ "description": "Total non-deleted actions on the team." }).check(Schema.isInt()), "recent": Schema.Array(RecentActionEntry).annotate({ "description": "The 5 most recently updated actions." }) }).annotate({ "description": "`inventory.recent_actions` — total + the 5 most recently modified." }), "top_events": Schema.Union([Schema.Array(Schema.Struct({ "window_days": Schema.Number.annotate({ "description": "Rolling lookback window (in days) that every count and timestamp on this row is measured over — these are windowed figures, NOT lifetime totals. A capture gap can collapse a real, high-volume project's in-window counts to near-zero, so a thin `count` here does not by itself mean the project is low-volume: rule out an ingestion gap (compare against a trailing baseline via a direct `execute-sql`) before closing out a surface as unused." }).check(Schema.isInt()), "event": Schema.String.annotate({ "description": "Event name as captured." }), "count": Schema.Number.annotate({ "description": "Number of occurrences within the last `window_days` (windowed, not lifetime)." }).check(Schema.isInt()), "distinct_users": Schema.Number.annotate({ "description": "`uniq(person_id)` over the window — reach. Distinguishes a high-count event firing on one power user from one firing on many users." }).check(Schema.isInt()), "recent_24h_count": Schema.Number.annotate({ "description": "Count in just the last 24 hours. Compare to `count / window_days` to spot bursts: a ratio well above `1 / window_days` means the event is concentrated in the last day." }).check(Schema.isInt()), "recent_24h_users": Schema.Number.annotate({ "description": "`uniq(person_id)` over just the last 24 hours. A burst across many users is qualitatively different from one user in a loop." }).check(Schema.isInt()), "first_seen_in_window": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "ISO-8601 timestamp of the earliest occurrence within the `window_days` window. Compare to the window start to spot new event types: close to `now` ⇒ likely new or recently bursting; close to the window edge ⇒ has been around at least that long (the window can't tell you when the event *truly* first appeared)." }), "last_seen_in_window": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "ISO-8601 timestamp of the most recent occurrence within the `window_days` window." }) }).annotate({ "description": "One row in `inventory.top_events`." })).annotate({ "description": "Top ~50 events by count over a recent rolling window (each row carries `window_days`), with first/last seen timestamps within that window. These are WINDOWED counts, not lifetime totals: a capture gap can collapse a real, high-volume project's counts to near-zero here, so rule out an ingestion gap (compare against a trailing baseline via a direct `execute-sql`) before reading thinness as a genuinely low-volume project. `null` if the underlying ClickHouse query failed or timed out (distinct from `[]`, which means the team has no captures in the window). Use the gap between `first_seen_in_window` and `now` to spot new event types or recent bursts." })]) }).annotate({ "description": "The deterministic inventory layer of a project profile.\n\nRead this to orient on the team's product mix, integrations, warehouse sources, signal\ncoverage, and existing inbox surface in one tool call. Distinct from `SignalScratchpad`:\nprofile is ground truth from authoritative tables; memory is agent inference." }) }).annotate({ "description": "Top-level `payload` shape on a `SignalProjectProfile` row.\n\nv1 carries `inventory` only. Phase 7 will add `deltas`, `activity_notes`, and\n`narrative` slots — they're absent (not null) in v1 responses." }) }).annotate({ "description": "Wire shape for the project profile returned by `signals-scout-harness-project-profile-list`.\n\nRead this once at the start of a run (after `skill-get`) to orient on the team. Cache\nis per-team with a soft TTL (`PROFILE_TTL`); the response always reflects either the\nlatest cached profile or a freshly-built one if the cache was stale or the caller passed\n`force_refresh=true`." })
