export const EmitFindingRequest = Schema.Struct({ "description": Schema.String.annotate({ "description": "Canonical evidence-bundle prose. Becomes the signal's `description`." }).check(Schema.isMaxLength(50000)), "confidence": Schema.Number.annotate({ "description": "Agent's confidence the finding is real in [0, 1]. Persisted in `extra`.", "format": "double" }).check(Schema.isFinite()).check(Schema.isGreaterThanOrEqualTo(0)).check(Schema.isLessThanOrEqualTo(1)), "evidence": Schema.Array(EvidenceEntry).annotate({ "description": "Citations supporting the finding. Capped at 20 entries." }).check(Schema.isMaxLength(20)), "hypothesis": Schema.optionalKey(Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Optional one-line hypothesis the finding tests." })), "severity": Schema.optionalKey(Schema.Union([AutonomyPriorityEnum, NullEnum], { mode: "oneOf" }).annotate({ "description": "Optional severity tag — one of P0, P1, P2, P3, P4. Informational only.\n\n* `P0` - P0\n* `P1` - P1\n* `P2` - P2\n* `P3` - P3\n* `P4` - P4" })), "dedupe_keys": Schema.optionalKey(Schema.Array(Schema.String).annotate({ "description": "Optional keys for downstream dedupe (e.g. `error_tracking_issue:<id>`)." })), "tags": Schema.optionalKey(Schema.Array(Schema.String.check(Schema.isMaxLength(50))).annotate({ "description": "Optional category tags as lowercase kebab-case slugs (e.g. `cost-spike`, `silent-failure`), max 10. Reuse the vocabulary in your `tags:<domain>:taxonomy` scratchpad entry when a tag fits; coin a new slug when a genuinely new category emerges. Near-miss formats are normalized to slugs; persisted in the signal's `extra.tags` and on the emission row." }).check(Schema.isMaxLength(10))), "time_range": Schema.optionalKey(Schema.Union([TimeRange, Schema.Null], { mode: "oneOf" }).annotate({ "description": "Optional time window the finding refers to." })), "mcp_trace_id": Schema.optionalKey(Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Optional MCP trace id for cross-system debugging." })), "finding_id": Schema.optionalKey(Schema.Union([Schema.String.check(Schema.isMaxLength(100, { "description": "Stable id for this finding, baked into the signal's source_id for traceability. NOT a dedupe key — re-emitting the same id creates another signal." }))])) }).annotate({ "description": "Request body for `emit-finding`. Run attribution is taken from the URL path." })
