export const RepoOverview = Schema.Struct({ "cost_series": Schema.Array(CostPerMergeBucket).annotate({ "description": "CI cost per merged PR across the window, oldest first, zero-filled, bucketed by cost_series_granularity. Empty when the job-level source isn't synced or include_series=false." }), "time_to_green_series": Schema.Array(TimeToGreenBucket).annotate({ "description": "Median time-to-green (p50 successful PR-attributed CI run duration) per bucket across the window, oldest first, bucketed by time_to_green_series_granularity. Empty buckets carry null; the whole series is empty when include_series=false." }), "success_rate_series": Schema.Array(PassRateBucket).annotate({ "description": "CI pass rate (completed runs that succeeded, all branches) per bucket across the window, oldest first, bucketed by success_rate_series_granularity. Empty buckets carry null; the whole series is empty when include_series=false." }), "open_to_merge_series": Schema.Array(OpenToMergeBucket).annotate({ "description": "Median time-to-merge (p50 open_to_merge_seconds, bots/drafts excluded) per bucket across the window, oldest first, bucketed by open_to_merge_series_granularity. Empty buckets carry null; the whole series is empty when include_series=false." }), "run_count": Schema.Number.annotate({ "description": "Workflow runs started in the window, all branches and workflows." }).check(Schema.isInt()), "run_count_prev": Schema.Number.annotate({ "description": "Same count over the equal-length window immediately before date_from — the delta baseline." }).check(Schema.isInt()), "success_rate": Schema.Never, "success_rate_prev": Schema.Never, "rerun_cycles": Schema.Number.annotate({ "description": "Runs in the window that were a 2nd+ attempt (attempt > 1)." }).check(Schema.isInt()), "rerun_cycles_prev": Schema.Number.annotate({ "description": "Re-run cycles over the previous window." }).check(Schema.isInt()), "merged_pr_count": Schema.Number.annotate({ "description": "PRs merged in the window, all authors and bots included — the merge population that triggered the CI spend, so it divides cleanly into billable_minutes and estimated_cost_usd." }).check(Schema.isInt()), "merged_pr_count_prev": Schema.Number.annotate({ "description": "Merged-PR count over the previous window." }).check(Schema.isInt()), "median_open_to_merge_seconds": Schema.Never, "median_open_to_merge_seconds_prev": Schema.Never, "billable_minutes": Schema.Never, "billable_minutes_prev": Schema.Never, "estimated_cost_usd": Schema.Never, "estimated_cost_usd_prev": Schema.Never, "jobs_available": Schema.Boolean.annotate({ "description": "Whether the job-level source is synced (cost and queue figures exist)." }), "default_branch": Schema.String.annotate({ "description": "'master' or 'main', picked by observed run volume in the window." }), "cost_series_granularity": Schema.String.annotate({ "description": "Bucket width of the cost_series trend, chosen to fit the window: 'hour', 'day', or 'week'." }), "time_to_green_series_granularity": Schema.String.annotate({ "description": "Bucket width of the time_to_green_series trend: 'hour', 'day', or 'week'." }), "success_rate_series_granularity": Schema.String.annotate({ "description": "Bucket width of the success_rate_series trend: 'hour', 'day', or 'week'." }), "open_to_merge_series_granularity": Schema.String.annotate({ "description": "Bucket width of the open_to_merge_series trend: 'hour', 'day', or 'week'." }) })
